import type { ProviderBStorage, Reservation, Service, ServiceResponse, Stock } from "./types";
import { error, parseReservationCommand, reservationResponse } from "./reservation";
import {
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeDecimal,
  isRecord,
  isRevision,
} from "./validation";

type ReadMissing = { kind: "missing" };
type ReadUnavailable = { kind: "unavailable" };
type ReadFound<T> = { kind: "found"; value: T };
type ReadResult<T> = ReadMissing | ReadUnavailable | ReadFound<T>;

function decodeReadEnvelope(value: unknown): { kind: "found"; value: unknown } | ReadMissing | ReadUnavailable {
  if (!isRecord(value) || typeof value.ok !== "boolean") return { kind: "unavailable" };
  if (value.ok) {
    return Object.hasOwn(value, "value") ? { kind: "found", value: value.value } : { kind: "unavailable" };
  }
  if (!isRecord(value.error) || value.error.reason !== "NO_SUCH_KEY") return { kind: "unavailable" };
  return { kind: "missing" };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<ReadResult<Stock>> {
  const envelope = decodeReadEnvelope(await storage.read({ collection: "inventory", key: sku }));
  if (envelope.kind !== "found") return envelope;
  const stock = decodeProviderBStockRow(envelope.value);
  return stock !== undefined && stock.sku === sku
    ? { kind: "found", value: stock }
    : { kind: "unavailable" };
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<ReadResult<Reservation>> {
  const envelope = decodeReadEnvelope(await storage.read({ collection: "reservations", key: reservationId }));
  if (envelope.kind !== "found") return envelope;
  const reservation = decodeProviderBReservationRow(envelope.value);
  return reservation !== undefined && reservation.reservationId === reservationId
    ? { kind: "found", value: reservation }
    : { kind: "unavailable" };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock.kind === "missing") return error(404, "stock_not_found");
          if (stock.kind === "unavailable") return error(500, "storage_unavailable");
          return {
            status: 200,
            body: {
              sku: stock.value.sku,
              totalUnits: stock.value.totalUnits,
              reservedUnits: stock.value.reservedUnits,
              availableUnits: stock.value.totalUnits - stock.value.reservedUnits,
            },
          };
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing.kind === "found"
            ? reservationResponse(200, existing.value)
            : error(404, "reservation_not_found");
        }

        if (existing.kind === "found") {
          return existing.value.sku === command.sku && existing.value.quantity === command.quantity
            ? reservationResponse(200, existing.value)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock.kind === "missing") return error(404, "stock_not_found");
        if (stock.kind === "unavailable") return error(500, "storage_unavailable");
        if (stock.value.totalUnits - stock.value.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const nextRevision = stock.value.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const unitsText = encodeDecimal(command.quantity);
        const outcome = await storage.commitBatch({
          expectedRevisionText: encodeDecimal(stock.value.revision),
          stockRow: {
            itemKey: command.sku,
            onHandText: encodeDecimal(stock.value.totalUnits),
            heldText: encodeDecimal(stock.value.reservedUnits + command.quantity),
            revisionText: encodeDecimal(nextRevision),
          },
          reservationRow: {
            bookingKey: command.reservationId,
            itemKey: command.sku,
            unitsText,
          },
          outboxRows: [{
            key: "reservation.created:" + command.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: command.reservationId,
              itemKey: command.sku,
              unitsText,
            },
          }],
        });

        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

